import { connection } from 'next/server';

export default async function ServerTimestamp() {
  // Await connection() to opt out of static prerendering
  await connection();

  return (
    <div>
      <p>Server Timestamp: {new Date().toISOString()}</p>
    </div>
  );
}

import ServerTimestamp from './components/ServerTimestamp';

export default function Home() {
  return (
    <main style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h1>Dynamic Timestamp Example</h1>
      <p>The timestamp below is generated on the server for every request.</p>
      <ServerTimestamp />
    </main>
  );
}

